package com.medicore.payment.service; import com.medicore.payment.dto.*; import com.medicore.payment.entity.Payment; import com.medicore.payment.repository.PaymentRepository; import org.springframework.stereotype.Service; import java.util.Set; @Service public class PaymentService {private final PaymentRepository repository; public PaymentService(PaymentRepository repository){this.repository=repository;} public PaymentResponse create(PaymentRequest r){return response(repository.save(new Payment(r.orderId(),r.amount())));} public PaymentResponse find(Long id){return response(repository.findById(id).orElseThrow(()->new IllegalArgumentException("Payment not found")));} public PaymentResponse status(Long id,String status){if(!Set.of("PENDING","AUTHORIZED","CAPTURED","FAILED","REFUNDED").contains(status))throw new IllegalArgumentException("Invalid status");Payment p=repository.findById(id).orElseThrow(()->new IllegalArgumentException("Payment not found"));p.setStatus(status);return response(repository.save(p));} private PaymentResponse response(Payment p){return new PaymentResponse(p.getId(),p.getOrderId(),p.getAmount(),p.getStatus());}}
